   302→// readCheckpointMetadata reads metadata.json from a checkpoint path on entire/checkpoints/v1.
   303→// With the new format, root metadata.json is a CheckpointSummary with Agents array.
   304→// This function reads the summary and extracts relevant fields into CheckpointInfo,
   305→// also reading session-level metadata for IsTask/ToolUseID fields.
   306→func ReadCheckpointMetadata(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
   307→	metadataPath := checkpointPath + "/metadata.json"
   308→	file, err := tree.File(metadataPath)
   309→	if err != nil {
   310→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
   311→	}
   312→
   313→	content, err := file.Contents()
   314→	if err != nil {
   315→		return nil, fmt.Errorf("failed to read metadata: %w", err)
   316→	}
   317→
   318→	// Try to parse as CheckpointSummary first (new format)
   319→	var summary checkpoint.CheckpointSummary
   320→	if err := json.Unmarshal([]byte(content), &summary); err == nil {
   321→		// If we have sessions array, this is the new format
   322→		if len(summary.Sessions) > 0 {
   323→			info := &CheckpointInfo{
   324→				CheckpointID:     summary.CheckpointID,
   325→				CheckpointsCount: summary.CheckpointsCount,
   326→				FilesTouched:     summary.FilesTouched,
   327→				SessionCount:     len(summary.Sessions),
   328→			}
   329→
   330→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
   331→			var sessionIDs []string
   332→			for i, sessionPaths := range summary.Sessions {
   333→				if sessionPaths.Metadata != "" {
   334→					// SessionFilePaths now contains absolute paths with leading "/"
   335→					// Strip the leading "/" for tree.File() which expects paths without leading slash
   336→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
   337→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
   338→						if sessionContent, err := sessionFile.Contents(); err == nil {
   339→							var sessionMetadata checkpoint.CommittedMetadata
   340→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   341→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
   342→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
   343→								if i == 0 {
   344→									info.Agent = sessionMetadata.Agent
   345→									info.SessionID = sessionMetadata.SessionID
   346→									info.CreatedAt = sessionMetadata.CreatedAt
   347→									info.IsTask = sessionMetadata.IsTask
   348→									info.ToolUseID = sessionMetadata.ToolUseID
   349→								}
   350→							}
   351→						}
   352→					}
   353→				}
   354→			}
   355→			info.SessionIDs = sessionIDs
   356→
   357→			return info, nil
   358→		}
   359→	}
   360→
   361→	// Fall back to parsing as CheckpointInfo (old format or direct info)
   362→	var metadata CheckpointInfo
   363→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
   364→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
   365→	}
   366→
   367→	return &metadata, nil
   368→}
