   419→// ReadSessionPromptFromTree reads the first meaningful prompt from a checkpoint's prompt.txt file in a git tree.
   420→// Returns an empty string if the prompt cannot be read.
   421→func ReadSessionPromptFromTree(tree *object.Tree, checkpointPath string) string {
   422→	promptPath := checkpointPath + "/" + paths.PromptFileName
   423→	file, err := tree.File(promptPath)
   424→	if err != nil {
   425→		return ""
   426→	}
   427→
   428→	content, err := file.Contents()
   429→	if err != nil {
   430→		return ""
   431→	}
   432→
   433→	return ExtractFirstPrompt(content)
   434→}
