   436→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
   437→func isOnlySeparators(s string) bool {
   438→	for _, r := range s {
   439→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
   440→			return false
   441→		}
   442→	}
   443→	return true
   444→}
