  1171→// branchExistsCLI checks if a branch exists using git CLI.
  1172→// Returns nil if the branch exists, or an error if it does not.
  1173→func branchExistsCLI(branchName string) error {
  1174→	ctx := context.Background()
  1175→	cmd := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
  1176→	if err := cmd.Run(); err != nil {
  1177→		return fmt.Errorf("branch %s not found: %w", branchName, err)
  1178→	}
  1179→	return nil
  1180→}
