  1182→// HardResetWithProtection performs a git reset --hard to the specified commit.
  1183→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
  1184→// deletes untracked directories (like .entire/) even when they're in .gitignore.
  1185→// Returns the short commit ID (7 chars) on success for display purposes.
  1186→func HardResetWithProtection(commitHash plumbing.Hash) (shortID string, err error) {
  1187→	ctx := context.Background()
  1188→	hashStr := commitHash.String()
  1189→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr) //nolint:gosec // hashStr is a plumbing.Hash, not user input
  1190→	if output, err := cmd.CombinedOutput(); err != nil {
  1191→		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
  1192→	}
  1193→
  1194→	// Return short commit ID for display
  1195→	shortID = hashStr
  1196→	if len(shortID) > 7 {
  1197→		shortID = shortID[:7]
  1198→	}
  1199→	return shortID, nil
  1200→}
