  1202→// collectUntrackedFiles collects all untracked files in the working directory.
  1203→// This is used to capture the initial state when starting a session,
  1204→// ensuring untracked files present at session start are preserved during rewind.
  1205→// Excludes protected directories (.git/, .entire/, and agent config directories).
  1206→// Works correctly from any subdirectory within the repository.
  1207→func collectUntrackedFiles() ([]string, error) {
  1208→	// Get repository root to walk from there
  1209→	repoRoot, err := GetWorktreePath()
  1210→	if err != nil {
  1211→		repoRoot = "." // Fallback to current directory
  1212→	}
  1213→
  1214→	var untrackedFiles []string
  1215→	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
  1216→		if walkErr != nil {
  1217→			return nil //nolint:nilerr // Skip filesystem errors during walk
  1218→		}
  1219→
  1220→		// Get path relative to repo root
  1221→		relPath, err := filepath.Rel(repoRoot, path)
  1222→		if err != nil {
  1223→			return nil //nolint:nilerr // Skip paths we can't make relative
  1224→		}
  1225→
  1226→		// Skip directories
  1227→		if info.IsDir() {
  1228→			if isProtectedPath(relPath) {
  1229→				return filepath.SkipDir
  1230→			}
  1231→			return nil
  1232→		}
  1233→
  1234→		// Skip files in protected directories (shouldn't reach here due to SkipDir, but safety check)
  1235→		if isProtectedPath(relPath) {
  1236→			return nil
  1237→		}
  1238→
  1239→		untrackedFiles = append(untrackedFiles, relPath)
  1240→		return nil
  1241→	})
  1242→	if err != nil {
  1243→		return nil, fmt.Errorf("failed to walk directory: %w", err)
  1244→	}
  1245→
  1246→	return untrackedFiles, nil
  1247→}
