  1249→// ExtractSessionIDFromCommit extracts the session ID from a commit's trailers.
  1250→// It checks the Entire-Session trailer first, then falls back to extracting from
  1251→// the metadata directory path in the Entire-Metadata trailer.
  1252→// Returns empty string if no session ID is found.
  1253→func ExtractSessionIDFromCommit(commit *object.Commit) string {
  1254→	// Try Entire-Session trailer first
  1255→	if sessionID, found := trailers.ParseSession(commit.Message); found {
  1256→		return sessionID
  1257→	}
  1258→
  1259→	// Try extracting from metadata directory (last path component)
  1260→	if metadataDir, found := trailers.ParseMetadata(commit.Message); found {
  1261→		return filepath.Base(metadataDir)
  1262→	}
  1263→
  1264→	return ""
  1265→}
