  1276→// createCommit creates a commit object
  1277→func createCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) { //nolint:unparam // already present in codebase
  1278→	now := time.Now()
