  1310→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
  1311→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
  1312→//
  1313→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
  1314→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
  1315→// the session directory, e.g., auto-commit strategy's sharded metadata), then falls back to
  1316→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
  1317→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
  1318→	// Helper to read first line from a file in tree
  1319→	readFirstLine := func(path string) string {
  1320→		file, err := tree.File(path)
  1321→		if err != nil {
  1322→			return ""
  1323→		}
  1324→		content, err := file.Contents()
  1325→		if err != nil {
  1326→			return ""
  1327→		}
  1328→		lines := strings.SplitN(content, "\n", 2)
  1329→		if len(lines) > 0 && lines[0] != "" {
  1330→			desc := strings.TrimSpace(lines[0])
  1331→			// Remove markdown header prefix if present
  1332→			return strings.TrimPrefix(desc, "# ")
  1333→		}
  1334→		return ""
  1335→	}
  1336→
  1337→	// If metadataDir is provided, look there directly
  1338→	if metadataDir != "" {
  1339→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
  1340→			return desc
  1341→		}
  1342→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
  1343→			return desc
  1344→		}
  1345→		return NoDescription
  1346→	}
  1347→
  1348→	// No metadataDir provided - first try looking at the root of the tree
  1349→	// (used when the tree is already the session directory)
  1350→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
  1351→		return desc
  1352→	}
  1353→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
  1354→		return desc
  1355→	}
  1356→
  1357→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
  1358→	// (used when the tree is the full worktree)
  1359→	var desc string
  1360→	//nolint:errcheck // We ignore errors here as we're just searching for a description
  1361→	_ = tree.Files().ForEach(func(f *object.File) error {
  1362→		if desc != "" {
  1363→			return nil // Already found description
  1364→		}
  1365→		name := f.Name
  1366→		if strings.Contains(name, ".entire/metadata/") {
  1367→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
  1368→				content, err := f.Contents()
  1369→				if err != nil {
  1370→					return nil //nolint:nilerr // Skip files we can't read, continue searching
  1371→				}
  1372→				lines := strings.SplitN(content, "\n", 2)
  1373→				if len(lines) > 0 && lines[0] != "" {
  1374→					desc = strings.TrimSpace(lines[0])
  1375→					desc = strings.TrimPrefix(desc, "# ")
  1376→				}
  1377→			}
  1378→		}
  1379→		return nil
  1380→	})
  1381→
  1382→	if desc != "" {
  1383→		return desc
  1384→	}
  1385→	return NoDescription
  1386→}
