  1388→// GetGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1389→// It checks local config first, then falls back to global config.
  1390→// Returns ("Unknown", "unknown@local") if no user is configured - this allows
  1391→// operations to proceed even without git user config, which is especially useful
  1392→// for internal metadata commits on branches like entire/checkpoints/v1.
  1393→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1394→	// Get repository config (includes local settings)
  1395→	cfg, err := repo.Config()
  1396→	if err == nil {
  1397→		name = cfg.User.Name
  1398→		email = cfg.User.Email
  1399→	}
  1400→
  1401→	// If not found in local config, try global config
  1402→	if name == "" || email == "" {
  1403→		globalCfg, err := config.LoadConfig(config.GlobalScope)
  1404→		if err == nil {
  1405→			if name == "" {
  1406→				name = globalCfg.User.Name
  1407→			}
  1408→			if email == "" {
  1409→				email = globalCfg.User.Email
  1410→			}
  1411→		}
  1412→	}
  1413→
  1414→	// Provide sensible defaults if git user is not configured
  1415→	if name == "" {
  1416→		name = "Unknown"
  1417→	}
  1418→	if email == "" {
  1419→		email = "unknown@local"
  1420→	}
  1421→
  1422→	return name, email
  1423→}
