  1425→// GetCurrentBranchName returns the short name of the current branch if HEAD points to a branch.
  1426→// Returns an empty string if in detached HEAD state or if there's an error reading HEAD.
  1427→// This is used to capture branch metadata for checkpoints.
  1428→func GetCurrentBranchName(repo *git.Repository) string {
  1429→	head, err := repo.Head()
  1430→	if err != nil || !head.Name().IsBranch() {
  1431→		return ""
  1432→	}
  1433→	return head.Name().Short()
  1434→}
  1435→
  1436→// getMainBranchHash returns the hash of the main branch (main or master).
  1437→// Returns ZeroHash if no main branch is found.
  1438→func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
  1439→	// Try common main branch names
  1440→	for _, branchName := range []string{branchMain, branchMaster} {
  1441→		// Try local branch first
  1442→		ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
  1443→		if err == nil {
  1444→			return ref.Hash()
  1445→		}
  1446→		// Try remote tracking branch
  1447→		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
  1448→		if err == nil {
  1449→			return ref.Hash()
  1450→		}
  1451→	}
  1452→	return plumbing.ZeroHash
  1453→}
  1454→
  1455→// GetDefaultBranchName returns the name of the default branch.
  1456→// First checks origin/HEAD, then falls back to checking if main/master exists.
  1457→// Returns empty string if unable to determine.
  1458→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1459→func GetDefaultBranchName(repo *git.Repository) string {
  1460→	// Try to get the symbolic reference for origin/HEAD
  1461→	// Use resolved=false to get the symbolic ref itself, then extract its target
  1462→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), false)
  1463→	if err == nil && ref != nil && ref.Type() == plumbing.SymbolicReference {
  1464→		target := ref.Target().String()
  1465→		if branchName, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
  1466→			return branchName
  1467→		}
  1468→	}
  1469→
  1470→	// Fallback: check if origin/main or origin/master exists
  1471→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMain), true); err == nil {
  1472→		return branchMain
  1473→	}
  1474→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMaster), true); err == nil {
  1475→		return branchMaster
  1476→	}
  1477→
  1478→	// Final fallback: check local branches
  1479→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMain), true); err == nil {
  1480→		return branchMain
  1481→	}
  1482→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMaster), true); err == nil {
  1483→		return branchMaster
  1484→	}
  1485→
  1486→	return ""
  1487→}
  1488→
  1489→// IsOnDefaultBranch checks if the repository HEAD is on the default branch.
  1490→// Returns (isOnDefault, currentBranchName).
  1491→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1492→func IsOnDefaultBranch(repo *git.Repository) (bool, string) {
  1493→	currentBranch := GetCurrentBranchName(repo)
  1494→	if currentBranch == "" {
  1495→		return false, ""
  1496→	}
  1497→
  1498→	defaultBranch := GetDefaultBranchName(repo)
  1499→	if defaultBranch == "" {
  1500→		// Can't determine default, check common names
  1501→		if currentBranch == branchMain || currentBranch == branchMaster {
  1502→			return true, currentBranch
  1503→		}
  1504→		return false, currentBranch
  1505→	}
  1506→
  1507→	return currentBranch == defaultBranch, currentBranch
  1508→}
